@import "@fontsource-variable/mona-sans/standard.css";
@import "@fontsource-variable/jetbrains-mono";

/* Light sibling: white page, the original's near-black (#020202) as ink, its two greys for
   secondary text, #cccccc hairlines and #f5f5f5 panels (both seen on its cookie banner), a
   black pill button, and the three signal colours darkened enough to read on white. */
:root {
  --background: #ffffff;
  --foreground: #020202;
  --card: #f5f5f5;
  --card-foreground: #020202;
  --popover: #ffffff;
  --popover-foreground: #020202;
  --primary: #020202;
  --primary-foreground: #ffffff;
  --secondary: #f5f5f5;
  --secondary-foreground: #020202;
  --muted: #e6e6e6;
  --muted-foreground: #6d6e71;
  --accent: #efefef;
  --accent-foreground: #020202;
  --destructive: #d93a14;
  --destructive-foreground: #ffffff;
  --border: #cccccc;
  --input: #cccccc;
  --ring: #6d6e71;
  --highlight: #0a9a49;
  --highlight-foreground: #ffffff;
  --glow: #1f7ae0;
  --chart-1: #e8480f;
  --chart-2: #1f7ae0;
  --chart-3: #0a9a49;
  --chart-4: #6d6e71;
  --chart-5: #939598;
  --sidebar: #f5f5f5;
  --sidebar-foreground: #020202;
  --sidebar-primary: #020202;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #efefef;
  --sidebar-accent-foreground: #020202;
  --sidebar-border: #cccccc;
  --sidebar-ring: #6d6e71;

  --typeface-body: "Mona Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Mona Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* Mona Sans is a touch wider than the original's Forma DJR: galaxy headings read this
     through [font-stretch:var(--galaxy-stretch,100%)] */
  --galaxy-stretch: 95%;
  --radius: 0.3125rem;
  --page-width: 90rem;
  --page-gutter: 1.5rem;
  --section-y: 3.5rem;
}

/* The original's rhythm steps up at desktop: 48px gutters, 96px section padding. */
@media (min-width: 64rem) {
  :root {
    --page-gutter: 3rem;
    --section-y: 6rem;
  }
}

/* Dark (faithful): #020202 page, white type, #939598 descriptions and #6d6e71 meta greys,
   #1c1c1c raised fills, #0a0a0a code card, #323232 hairlines, a white pill button, and the
   signal colours green #40ff88, orange #ff5a1f, blue #4da3ff. */
.dark {
  --background: #020202;
  --foreground: #ffffff;
  --card: #0a0a0a;
  --card-foreground: #ffffff;
  --popover: #0a0a0a;
  --popover-foreground: #ffffff;
  --primary: #ffffff;
  --primary-foreground: #020202;
  --secondary: #1c1c1c;
  --secondary-foreground: #ffffff;
  --muted: #1c1c1c;
  --muted-foreground: #939598;
  --accent: #1c1c1c;
  --accent-foreground: #ffffff;
  --destructive: #ff5a1f;
  --destructive-foreground: #020202;
  --border: #323232;
  --input: #323232;
  --ring: #939598;
  --highlight: #40ff88;
  --highlight-foreground: #020202;
  --glow: #4da3ff;
  --chart-1: #ff5a1f;
  --chart-2: #4da3ff;
  --chart-3: #40ff88;
  --chart-4: #939598;
  --chart-5: #6d6e71;
  --sidebar: #0a0a0a;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #ffffff;
  --sidebar-primary-foreground: #020202;
  --sidebar-accent: #1c1c1c;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #323232;
  --sidebar-ring: #939598;
}
